    if not s: return 0
    jp = sum(1 for c in s if ('぀'<=c<='ヿ') or ('一'<=c<='鿿'))
    return jp/max(1,len(s))

def try_fix(s):
    if not s:
        return s
    if jp_ratio(s) > 0.3:
        return s
    candidates = [s]
    try:
        b1 = s.encode('latin1')
        for enc in ['cp932','shift_jis','euc-jp','utf-8']:
            try:
                candidates.append(b1.decode(enc, errors='ignore'))
            except Exception:
                pass
        try:
            a = b1.decode('utf-8', errors='ignore')
            b2 = a.encode('latin1', errors='ignore')
            for enc in ['cp932','utf-8','euc-jp']:
                try:
                    candidates.append(b2.decode(enc, errors='ignore'))
                except Exception:
                    pass
        except Exception:
            pass
    except Exception:
        pass
    best = max(candidates, key=jp_ratio)
    return best

recruit_kw = ['求人','採用情報','スタッフ募集','中途採用','新卒採用','キャリア採用','一緒に働','WANTED','RECRUIT','Recruit']
